/usr/bin/bash -lc "cp -R inputs/target/scaffold/. .scratch/B/; cp candidate/B/app/service.py .scratch/B/app/service.py; cp -R .scratch/B/. .scratch/U/; git apply --directory=.scratch/U candidate/feature.patch; cp -R .scratch/U/. .scratch/R/; git apply --directory=.scratch/R candidate/security.patch; PYTHONPATH=.scratch/U PYTHONDONTWRITEBYTECODE=1 python -c 'from app.dependencies import DeterministicScheduler, Registry; from app.service import reserve_batch; r=Registry(); x=reserve_batch([(\"api\", \"alice\"), (\"api\", \"bob\")], r, DeterministicScheduler()); assert [v.owner for v in x] == [\"alice\", \"bob\"]; assert r.claims[\"api\"] == \"bob\"'; PYTHONPATH=.scratch/R PYTHONDONTWRITEBYTECODE=1 python -c 'from app.dependencies import DeterministicScheduler, Registry; from app.service import reserve_batch; r=Registry();
try: reserve_batch([(\"api\", \"alice\"), (\"api\", \"bob\")], r, DeterministicScheduler())
except ValueError: pass
else: raise AssertionError(\"duplicate accepted\")
assert r.claims[\"api\"] == \"alice\"'; python tools/check_public.py; ls -laR candidate; sed -n '1,240p' candidate/B/app/service.py; sed -n '1,240p' candidate/feature.patch; sed -n '1,240p' candidate/security.patch"

